1	package credit
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"unicode/utf8"
10	)
11	
12	// 本文件回归“保存时不得悄悄改写文字”。标准库 encoding/json 序列化会把字符串
13	// 中的非法 UTF-8 字节静默替换成 U+FFFD（“�”）却返回成功：若照常保存，免修
14	// 依据会被改掉，两个本来不同的编号还可能被替换成同一个编号，让原本可读的
15	// 记录文件变成编号重复的损坏文件。因此凡是要写入文件的文字——课程、学生、
16	// 课程要求、修读、免修的编号、名称、学期、依据、原因等——都必须是合法
17	// UTF-8；任何一条记录（哪怕是已拒绝或已撤销的免修）的任何一个字段不合法，
18	// 都必须拒绝整次保存：不修补/清空/替换原始字符串，不删除历史，不创建或
19	// 改动目标文件。合法文字（用户确实输入的“�”、补充平面字符、编号中合法的
20	// 控制字符、依据中原有的空白、字面上的“\uD800”）继续按原文保存。
21	
22	// badByte 是一个单独的非法 UTF-8 字节，放进任何字符串都会让该串非法。
23	var badByte = string([]byte{0xFF})
24	
25	// saveTextBaseStore 构造一份结构完整、各条引用齐全的记录，供用例把非法文字
26	// 注入某个具体字段：课程 c1、学生 s1、要求 r1、修读 e1（选课）、有效免修
27	// w1 与一条已拒绝免修 wbad。
28	func saveTextBaseStore(t *testing.T) *Store {
29		t.Helper()
30		s := NewStore()
31		mustCourse(t, s, "c1", "数学", 4)
32		mustStudent(t, s, "s1")
33		mustReq(t, s, "s1", "r1", "c1")
34		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
35		if w, _, err := s.ApplyWaiver("s1", "r1", "w1", "竞赛获奖依据"); err != nil || w.Status != WaiverApproved {
36			t.Fatalf("构造有效免修失败：%+v %v", w, err)
37		}
38		if w, _, err := s.ApplyWaiver("s1", "不存在的要求", "wbad", "旧依据"); err != nil ||
39			w.Status != WaiverRejected {
40			t.Fatalf("构造被拒绝免修失败：%+v %v", w, err)
41		}
42		return s
43	}
44	
45	// corruptField 在 store 中定位某个要校验的字符串字段并写入非法 UTF-8。
46	// 返回用于恢复断言的字段定位（类别、字段标签）。
47	type fieldTarget struct {
48		category string
49		field    string
50		corrupt  func(s *Store)
51		// rawField 返回被改字段当前的原始内容，供“未被修补”断言使用。
52		rawField func(s *Store) string
53	}
54	
55	func saveFieldTargets() []fieldTarget {
56		bad := "x" + badByte
57		return []fieldTarget{
58			{"课程", "编号", func(s *Store) { s.courses[0].ID = bad },
59				func(s *Store) string { return s.courses[0].ID }},
60			{"课程", "名称", func(s *Store) { s.courses[0].Name = bad },
61				func(s *Store) string { return s.courses[0].Name }},
62			{"学生", "编号", func(s *Store) { s.students[0].ID = bad },
63				func(s *Store) string { return s.students[0].ID }},
64			{"课程要求", "编号", func(s *Store) { s.requirements[0].ID = bad },
65				func(s *Store) string { return s.requirements[0].ID }},
66			{"课程要求", "学生编号", func(s *Store) { s.requirements[0].StudentID = bad },
67				func(s *Store) string { return s.requirements[0].StudentID }},
68			{"课程要求", "课程编号", func(s *Store) { s.requirements[0].CourseID = bad },
69				func(s *Store) string { return s.requirements[0].CourseID }},
70			{"修读", "编号", func(s *Store) { s.enrollments[0].ID = bad },
71				func(s *Store) string { return s.enrollments[0].ID }},
72			{"修读", "学生编号", func(s *Store) { s.enrollments[0].StudentID = bad },
73				func(s *Store) string { return s.enrollments[0].StudentID }},
74			{"修读", "要求编号", func(s *Store) { s.enrollments[0].ReqID = bad },
75				func(s *Store) string { return s.enrollments[0].ReqID }},
