399	// 这两个字段与编号、名称、学期、依据、原因遵守同一条 UTF-8 规则：用户确实输入
400	// 的“�”（U+FFFD）是合法字符，不能仅凭它出现在结果或状态文字中就判为非法
401	// 字节；只有真正的非法字节才拒绝。这里直接校验这两个字段的判定，避免与“结果/
402	// 状态只能取固定业务值”的既有读取规则（loadData 的枚举校验）混在一起——业务
403	// 允许的标准状态（通过/未通过、有效/已拒绝/已撤销）照常保存与读取由其余用例
404	// 覆盖。
405	func TestSaveResultStatusLegalReplacementCharAccepted(t *testing.T) {
406		for _, c := range []struct {
407			category, id, field, value string
408		}{
409			{"修读", "e1", "结果", "passed�-合法"},
410			{"修读", "e1", "结果", "未通过�"},
411			{"免修", "w1", "状态", "rejected�-状态"},
412			{"免修", "w1", "状态", "�"},
413		} {
414			if err := checkSaveText(c.category, c.id, c.field, c.value); err != nil {
415				t.Fatalf("%s记录 %s 的字段“%s”含合法 U+FFFD 时不应被判为非法文字：%v",
416					c.category, c.id, c.field, err)
417			}
418			// 同一文字中夹入真正的非法字节仍必须拒绝。
419			bad := c.value + badByte
420			err := checkSaveText(c.category, c.id, c.field, bad)
421			if err == nil {
422				t.Fatalf("%s记录 %s 的字段“%s”加入非法字节后必须拒绝", c.category, c.id, c.field)
423			}
424			var ite *invalidTextError
425			if !errors.As(err, &ite) || ite.category != c.category || ite.field != c.field || ite.id != c.id {
426				t.Fatalf("错误应点名类别 %q、编号 %q 与字段 %q，得到：%v",
427					c.category, c.id, c.field, err)
428			}
429		}
