453	// 用户确实输入的“�”、中文与补充平面字符、编号中合法的控制字符、免修依据
454	// 中原有（含前后）的空白、命令行字面上的“\uD800”（反斜线加普通字母数字，
455	// 不是 Unicode 转义）都不能被误拒绝。
456	func TestSaveAcceptsLegalUnicodeText(t *testing.T) {
457		dir := t.TempDir()
458		path := filepath.Join(dir, "records.json")
459	
460		s := NewStore()
461		// 编号中合法的控制字符（U+0001）与用户确实输入的“�”。
462		mustStudent(t, s, "s\u0001")
463		mustStudent(t, s, "s�2")
464		// 中文与补充平面字符课程名称。
465		mustCourse(t, s, "c1", "高等数学😀", 4)
466		mustReq(t, s, "s\u0001", "r1", "c1")
467		// 学期含补充平面字符、修读编号含“�”。
468		mustEnroll(t, s, "s\u0001", "r1", "2024😀春", "e�1")
469		if _, _, err := s.SubmitResult("s\u0001", "e�1", Passed); err != nil {
470			t.Fatal(err)
471		}
472		// 依据前后与中间的空白必须原样保留；命令行里字面出现的“\uD800”只是
473		// 反斜线加普通字母数字（合法 ASCII 文字），不是记录文件里的 Unicode 转义。
474		literalBackslashU := `\uD800`
475		basis := "  竞赛\n获奖\t" + literalBackslashU + "  "
476		if w, _, err := s.ApplyWaiver("s\u0001", "r1", "w1", basis); err != nil ||
477			w.Status != WaiverApproved {
478			t.Fatalf("含空白与字面 \\uD800 的依据应正常生效：%+v %v", w, err)
479		}
480	
481		if err := s.Save(path); err != nil {
482			t.Fatalf("合法文字应正常保存：%v", err)
483		}
484	
485		loaded, _, err := Load(path)
486		if err != nil {
487			t.Fatalf("合法文字保存后应可正常读取：%v", err)
488		}
489		if loaded.Student("s\u0001") == nil {
490			t.Fatal("编号中合法的控制字符应原样保存")
491		}
492		if loaded.Student("s�2") == nil {
493			t.Fatal("用户确实输入的“�”是合法文字，应原样保存")
494		}
495		if c := loaded.Course("c1"); c == nil || c.Name != "高等数学😀" {
496			t.Fatalf("中文与补充平面字符应原样保存，得到 %+v", c)
497		}
498		if e := loaded.Enrollment("s\u0001", "e�1"); e == nil || e.Term != "2024😀春" {
499			t.Fatalf("含补充平面字符的学期与含“�”的修读编号应原样保存，得到 %+v", e)
500		}
501		w := loaded.Waiver("s\u0001", "w1")
502		if w == nil || w.Basis != basis || !strings.Contains(w.Basis, literalBackslashU) {
503			t.Fatalf("依据中的原有空白与字面 \\uD800 应原样保留，得到 %+v", w)
504		}
505		// 学分来源与核对结果不改变。
506		if rep := loaded.CheckStudent("s\u0001"); rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
507			t.Fatalf("正常保存后核对结果不应改变，得到 %+v", rep)
508		}
