204	
205	// TestLoadReorderedPassesPickEarliestSeqSource 一项 4 学分要求有两次通过
206	// 修读，文件把后提交的记录排在前面，且修读编号与学期的先后都与提交先后
207	// 相反：没有有效免修时仍以提交序号较小的通过修读说明来源，两次通过都保留，
208	// 要求满足、总学分仍是 4。
209	func TestLoadReorderedPassesPickEarliestSeqSource(t *testing.T) {
210		// 文件顺序 [e1(seq2, 2024春), e2(seq1, 2024秋)]：
211		// 按文件排列、编号升序、学期升序都会挑到 e1，只有提交序号指向 e2。
212		d := seqBaseRecord()
213		d.Enrollments = []*Enrollment{
214			seqEnr("e1", "s1", "r1", "2024春", Passed, 2),
215			seqEnr("e2", "s1", "r1", "2024秋", Passed, 1),
216		}
217		d.NextResultSeq = 2
218		path, _ := writeRecord(t, d)
219		s, existed, err := Load(path)
220		if err != nil || !existed {
221			t.Fatalf("序号各不相同的合法记录应正常读取，existed=%v err=%v", existed, err)
222		}
223		rep := s.CheckStudent("s1")
224		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
225			t.Fatalf("要求应满足且总学分仍是 4，得到学分=%d 未满足=%v",
226				rep.TotalCredits, rep.Unmet)
227		}
228		st := rep.Requirements[0]
229		if !st.Satisfied || st.Source != "enrollment" || st.PassedEnrollmentID != "e2" {
230			t.Fatalf("应以提交序号较小的通过修读 e2 说明来源，不能按文件排列/编号/学期挑选，得到 %+v", st)
231		}
232		if len(st.PassedEnrollmentIDs) != 2 ||
233			st.PassedEnrollmentIDs[0] != "e2" || st.PassedEnrollmentIDs[1] != "e1" {
234			t.Fatalf("两次通过记录都应按提交先后保留，得到 %v", st.PassedEnrollmentIDs)
235		}
236		if s.Dirty() {
237			t.Fatal("只读核对不应把记录标记为已变更")
238		}
239	
240		// 两条记录各自的结果、学期与序号保持原样。
241		e1 := s.Enrollment("s1", "e1")
242		e2 := s.Enrollment("s1", "e2")
243		if e1 == nil || e1.Result != Passed || e1.ResultSeq != 2 || e1.Term != "2024春" {
244			t.Fatalf("e1 应原样保留，得到 %+v", e1)
245		}
246		if e2 == nil || e2.Result != Passed || e2.ResultSeq != 1 || e2.Term != "2024秋" {
247			t.Fatalf("e2 应原样保留，得到 %+v", e2)
248		}
249	
250		// 用现有格式重新保存再加载：来源仍是序号最小的 e2，结论不漂移。
251		path2 := filepath.Join(t.TempDir(), "records.json")
252		if err := s.Save(path2); err != nil {
253			t.Fatalf("Save: %v", err)
254		}
255		reloaded, existed, err := Load(path2)
256		if err != nil || !existed {
257			t.Fatalf("重新保存后应可再次加载，existed=%v err=%v", existed, err)
258		}
259		rep2 := reloaded.CheckStudent("s1")
260		if rep2.TotalCredits != 4 || rep2.Requirements[0].PassedEnrollmentID != "e2" ||
261			len(rep2.Requirements[0].PassedEnrollmentIDs) != 2 {
262			t.Fatalf("重新加载后来源仍应是 e2、两次通过都保留，得到 %+v", rep2)
263		}
264	}
265	
266	// TestLoadEarlierFailedSubmissionStaysHistoryNotSource 存在比两次通过更早
267	// 提交的未通过修读时，它必须保留在修读历史中（结果与序号不变），但不能
268	// 取代序号最小的通过修读成为学分来源；总学分仍是一份 4 学分。
269	func TestLoadEarlierFailedSubmissionStaysHistoryNotSource(t *testing.T) {
270		// 文件排列刻意打乱：e1 未通过（序号 1、学期反而更晚），两条通过分别
271		// 是序号 3 的 e2 与序号 2 的 e3。来源应是通过修读中序号最小的 e3。
272		d := seqBaseRecord()
273		d.Enrollments = []*Enrollment{
274			seqEnr("e2", "s1", "r1", "2024秋", Passed, 3),
275			seqEnr("e1", "s1", "r1", "2025春", Failed, 1),
276			seqEnr("e3", "s1", "r1", "2024春", Passed, 2),
277		}
278		d.NextResultSeq = 3
279		s := loadLegalRecord(t, d)
280	
281		rep := s.CheckStudent("s1")
282		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
283			t.Fatalf("有通过修读时要求应满足、总学分 4，得到学分=%d 未满足=%v",
284				rep.TotalCredits, rep.Unmet)
285		}
286		st := rep.Requirements[0]
287		if st.Source != "enrollment" || st.PassedEnrollmentID != "e3" {
288			t.Fatalf("来源应是通过修读中序号最小的 e3，未通过不能成为来源，得到 %+v", st)
289		}
290		if len(st.PassedEnrollmentIDs) != 2 ||
291			st.PassedEnrollmentIDs[0] != "e3" || st.PassedEnrollmentIDs[1] != "e2" {
292			t.Fatalf("通过历史应只含两次通过并按序号排列，得到 %v", st.PassedEnrollmentIDs)
293		}
294	
295		// 更早提交的未通过记录保留在历史中，结果与序号不变。
296		failed := s.Enrollment("s1", "e1")
297		if failed == nil || failed.Result != Failed || failed.ResultSeq != 1 || failed.Term != "2025春" {
298			t.Fatalf("更早提交的未通过修读应原样保留在历史中，得到 %+v", failed)
299		}
300		if n := len(s.Enrollments("s1")); n != 3 {
301			t.Fatalf("三条修读记录都应保留，得到 %d 条", n)
302		}
303	}
304	
305	// TestLoadMultipleEnrolledZeroSeqLegalAndWorthNoCredit 只有选课、尚未提交
306	// 结果的修读统一使用序号 0：多条这样的修读同时存在（含同一学期重复修读、
307	// 跨学生并存）是合法记录，不能因共享 0 而报序号重复，也不能由此获得学分；
308	// 与已提交记录混放时结论也不变。
309	func TestLoadMultipleEnrolledZeroSeqLegalAndWorthNoCredit(t *testing.T) {
310		t.Run("只有多条选课", func(t *testing.T) {
311			d := seqBaseRecord()
312			d.Enrollments = []*Enrollment{
313				seqEnr("e1", "s1", "r1", "2024春", Enrolled, 0),
314				seqEnr("e2", "s1", "r1", "2024春", Enrolled, 0), // 同一学期重复修读
315				seqEnr("e3", "s1", "r1", "2024秋", Enrolled, 0),
316			}
317			d.NextResultSeq = 0
318			s := loadLegalRecord(t, d)
319			rep := s.CheckStudent("s1")
320			if rep.TotalCredits != 0 || len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
321				t.Fatalf("仅选课不应获得学分，r1 应未满足，得到学分=%d 未满足=%v",
322					rep.TotalCredits, rep.Unmet)
323			}
324			st := rep.Requirements[0]
325			if st.Satisfied || st.Source != "" || len(st.PassedEnrollmentIDs) != 0 {
326				t.Fatalf("选课记录不能成为来源或进入通过历史，得到 %+v", st)
327			}
328			if n := len(s.Enrollments("s1")); n != 3 {
329				t.Fatalf("三条选课记录都应保留，得到 %d 条", n)
330			}
331		})
332	
333		t.Run("多条选课与已提交记录及另一名学生并存", func(t *testing.T) {
334			d := seqBaseRecord()
335			d.Students = append(d.Students, &Student{ID: "s2"})
336			d.Requirements = append(d.Requirements, &Requirement{ID: "r1", StudentID: "s2", CourseID: "c1"})
337			d.Enrollments = []*Enrollment{
338				seqEnr("e1", "s1", "r1", "2024春", Enrolled, 0),
339				seqEnr("e2", "s1", "r1", "2024春", Enrolled, 0),
340				seqEnr("e3", "s1", "r1", "2024秋", Passed, 1),
341				seqEnr("e1", "s2", "r1", "2024春", Enrolled, 0), // 跨学生共享编号与序号 0
342			}
343			d.NextResultSeq = 1
344			s := loadLegalRecord(t, d)
345	
346			rep := s.CheckStudent("s1")
347			if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
348				t.Fatalf("s1 应只凭通过的 e3 获得 4 学分，得到学分=%d 未满足=%v",
349					rep.TotalCredits, rep.Unmet)
350			}
351			st := rep.Requirements[0]
352			if st.PassedEnrollmentID != "e3" || len(st.PassedEnrollmentIDs) != 1 {
353				t.Fatalf("来源应只有 e3，选课记录不得计入，得到 %+v", st)
354			}
355			// s2 的同号选课仍是选课、0 学分，不与 s1 的任何记录冲突。
356			rep2 := s.CheckStudent("s2")
357			if rep2.TotalCredits != 0 || len(rep2.Unmet) != 1 || rep2.Unmet[0] != "r1" {
358				t.Fatalf("s2 的选课应保持 0 学分未满足，得到 %+v", rep2)
359			}
360			if e := s.Enrollment("s2", "e1"); e == nil || e.Result != Enrolled || e.ResultSeq != 0 {
361				t.Fatalf("s2 名下应保留本人的选课 e1，得到 %+v", e)
362			}
363		})
364	}
365	
366	// TestLoadSubmittedSeqGapsNeedNotBeConsecutive 已提交序号允许有间隔，不要求
367	// 连续编号：跳号的合法记录正常读取，来源仍是通过记录中序号最小的一条，
368	// 未通过不成为来源，选课记录不得携带序号。
369	func TestLoadSubmittedSeqGapsNeedNotBeConsecutive(t *testing.T) {
370		d := seqBaseRecord()
371		d.Enrollments = []*Enrollment{
372			seqEnr("e1", "s1", "r1", "2024春", Failed, 1),
373			seqEnr("e2", "s1", "r1", "2024夏", Passed, 5), // 序号 2/3/4 缺失
374			seqEnr("e3", "s1", "r1", "2024秋", Passed, 9), // 继续跳号
375			seqEnr("e4", "s1", "r1", "2025春", Enrolled, 0),
376		}
377		d.NextResultSeq = 9
378		s := loadLegalRecord(t, d)
379	
380		rep := s.CheckStudent("s1")
381		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
382			t.Fatalf("跳号记录应正常核对到 4 学分，得到学分=%d 未满足=%v",
383				rep.TotalCredits, rep.Unmet)
384		}
385		st := rep.Requirements[0]
386		if st.Source != "enrollment" || st.PassedEnrollmentID != "e2" {
387			t.Fatalf("序号 1 的未通过不成为来源，应取通过中序号最小的 e2，得到 %+v", st)
388		}
389		if len(st.PassedEnrollmentIDs) != 2 ||
390			st.PassedEnrollmentIDs[0] != "e2" || st.PassedEnrollmentIDs[1] != "e3" {
391			t.Fatalf("两次通过应按序号保留为 [e2 e3]，得到 %v", st.PassedEnrollmentIDs)
392		}
393		if e := s.Enrollment("s1", "e4"); e == nil || e.Result != Enrolled || e.ResultSeq != 0 {
394			t.Fatalf("选课记录 e4 应保留且无序号，得到 %+v", e)
395		}
396	}
397	
398	// TestLoadSameEnrollmentIDAcrossStudentsDifferentSeq 不同学生可以共用修读
399	// 编号（学期也可相同），只要提交序号不同就各自保留所属记录：结果、序号、
400	// 学分来源各归本人，不能因编号或学期相同误报冲突或串记录。
401	func TestLoadSameEnrollmentIDAcrossStudentsDifferentSeq(t *testing.T) {
402		t.Run("一通过一未通过", func(t *testing.T) {
403			d := seqBaseRecord()
404			d.Courses = append(d.Courses, &Course{ID: "c2", Name: "线性代数", Credit: 3, Open: true})
405			d.Students = append(d.Students, &Student{ID: "s2"})
406			d.Requirements = append(d.Requirements, &Requirement{ID: "r1", StudentID: "s2", CourseID: "c2"})
407			d.Enrollments = []*Enrollment{
408				seqEnr("e1", "s1", "r1", "2024春", Passed, 1),
409				seqEnr("e1", "s2", "r1", "2024春", Failed, 2),
410			}
411			d.NextResultSeq = 2
412			path, raw := writeRecord(t, d)
413			s, existed, err := Load(path)
414			if err != nil || !existed {
415				t.Fatalf("跨学生同编号、序号不同应正常读取，existed=%v err=%v", existed, err)
416			}
417	
418			// s1：本人 e1 通过，4 学分，来源本人 e1。
419			rep1 := s.CheckStudent("s1")
420			if rep1.TotalCredits != 4 || len(rep1.Unmet) != 0 {
421				t.Fatalf("s1 应凭本人通过修读得 4 学分，得到学分=%d 未满足=%v",
422					rep1.TotalCredits, rep1.Unmet)
423			}
424			if st := rep1.Requirements[0]; st.Source != "enrollment" ||
425				st.PassedEnrollmentID != "e1" || st.Course.Credit != 4 {
426				t.Fatalf("s1 的来源应是本人 4 学分课程的 e1，得到 %+v", st)
427			}
428			// s2：本人 e1 未通过，0 学分，要求未满足。
429			rep2 := s.CheckStudent("s2")
430			if rep2.TotalCredits != 0 || len(rep2.Unmet) != 1 || rep2.Unmet[0] != "r1" {
431				t.Fatalf("s2 本人的 e1 未通过，应 0 学分未满足，得到 %+v", rep2)
432			}
433			if len(rep2.Requirements[0].PassedEnrollmentIDs) != 0 {
434				t.Fatalf("s2 不应有通过历史，得到 %+v", rep2.Requirements[0])
435			}
436	
437			// 同号修读是两条独立记录，结果与序号各归本人。
438			e1s1 := s.Enrollment("s1", "e1")
439			e1s2 := s.Enrollment("s2", "e1")
440			if e1s1 == nil || e1s2 == nil || e1s1 == e1s2 {
441				t.Fatalf("两名学生的同号修读应各自独立，得到 %p %p", e1s1, e1s2)
442			}
443			if e1s1.Result != Passed || e1s1.ResultSeq != 1 {
444				t.Fatalf("s1 的 e1 应保留通过、序号 1，得到 %+v", e1s1)
445			}
446			if e1s2.Result != Failed || e1s2.ResultSeq != 2 {
447				t.Fatalf("s2 的 e1 应保留未通过、序号 2，得到 %+v", e1s2)
448			}
449	
450			// 两人的只读核对都不得改动原文件。
451			_ = s.CheckStudent("s1")
452			_ = s.CheckStudent("s2")
453			got, readErr := os.ReadFile(path)
454			if readErr != nil {
455				t.Fatal(readErr)
456			}
457			if string(got) != string(raw) {
458				t.Fatal("只读核对不得改写跨学生的合法记录")
459			}
460		})
461	
462		t.Run("两人都通过_序号不同", func(t *testing.T) {
463			d := seqBaseRecord()
464			d.Courses = append(d.Courses, &Course{ID: "c2", Name: "线性代数", Credit: 3, Open: true})
465			d.Students = append(d.Students, &Student{ID: "s2"})
466			d.Requirements = append(d.Requirements, &Requirement{ID: "r1", StudentID: "s2", CourseID: "c2"})
467			d.Enrollments = []*Enrollment{
468				// 后提交的 s2 记录排在文件前面，证明来源只看序号、不看排列。
469				seqEnr("e1", "s2", "r1", "2024春", Passed, 2),
470				seqEnr("e1", "s1", "r1", "2024春", Passed, 1),
471			}
472			d.NextResultSeq = 2
473			s := loadLegalRecord(t, d)
474	
475			rep1 := s.CheckStudent("s1")
476			if rep1.TotalCredits != 4 || rep1.Requirements[0].PassedEnrollmentID != "e1" {
477				t.Fatalf("s1 应凭本人 e1 得 4 学分，得到 %+v", rep1)
478			}
479			rep2 := s.CheckStudent("s2")
480			if rep2.TotalCredits != 3 || rep2.Requirements[0].PassedEnrollmentID != "e1" {
481				t.Fatalf("s2 应凭本人 e1（另一门 3 学分课程）得 3 学分，得到 %+v", rep2)
482			}
483			// 两条同号通过各只属于本人，不能互相进入对方的通过历史。
484			if len(rep1.Requirements[0].PassedEnrollmentIDs) != 1 ||
485				len(rep2.Requirements[0].PassedEnrollmentIDs) != 1 {
486				t.Fatalf("两人的通过历史都应只有本人的一条，得到 %v / %v",
487					rep1.Requirements[0].PassedEnrollmentIDs,
488					rep2.Requirements[0].PassedEnrollmentIDs)
489			}
490		})
491	}
