48	// seqDupBase 构造结构完整、引用齐全的基础记录：s1 的要求 r1 指向 4 学分
49	// 课程 c1。修读列表由各用例自行拼入。
50	func seqDupBase() *diskRecord {
51		return &diskRecord{
52			Version:      1,
53			Courses:      []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
54			Students:     []diskStudent{{ID: "s1"}},
55			Requirements: []diskReq{{ID: "r1", Student: "s1", Course: "c1"}},
56		}
