93	// TestCLIDuplicateResultSeqOnePassedOneFailedRejected 两条同序号修读一条
94	// 通过、一条未通过时同样整份损坏：未通过也是一次独立的结果提交，不能因为
95	// 它不计学分就放过序号冲突。
96	func TestCLIDuplicateResultSeqOnePassedOneFailedRejected(t *testing.T) {
97		d := seqDupBase()
98		d.Enrollments = []diskEnr{
99			// 文件排列刻意把未通过放前面，证明判定不依赖排列顺序。
100			enrRecord("e2", "s1", "r1", "2024秋", "failed", 5),
101			enrRecord("e1", "s1", "r1", "2024春", "passed", 5),
102		}
