108			t.Fatalf("一通过一未通过共用序号也应整份拒绝，code=%d out=%q err=%q",
109				code, out, errText)
110		}
111		if !strings.Contains(errText, "结果提交序号 5 重复") || !strings.Contains(errText, file) {
112			t.Fatalf("错误应点名问题文件与重复序号 5，err=%q", errText)
