176		file, raw := writeDiskRecord(t, d)
177	
178		out, _, code := runCLI(t, file, "check", "s1")
179		if code != 0 {
180			t.Fatalf("序号各不相同的合法记录应正常核对，code=%d out=%q", code, out)
181		}
182		for _, want := range []string{
183			"总学分：4",
184			"要求 r1（课程 c1《高等数学》，4 学分）：已满足",
185			"来源为通过修读 e2",
186			"共通过 2 次，仅计一次学分",
187		} {
188			if !strings.Contains(out, want) {
