191		}
192		if strings.Contains(out, "来源为通过修读 e1") || strings.Contains(out, "未满足要求：[") {
193			t.Fatalf("不能按文件排列/编号/学期挑到 e1，也不应有未满足要求，out=%q", out)
194		}
