212	func cmdListCourses(s *credit.Store, out io.Writer) (int, error) {
213		courses := s.Courses()
214		if len(courses) == 0 {
215			fmt.Fprintln(out, "（尚无课程）")
216			return exitOK, nil
217		}
218		for _, c := range courses {
219			fmt.Fprintf(out, "课程 %s《%s》%d 学分，状态：%s\n", c.ID, c.Name, c.Credit, openText(c.Open))
220		}
221		return exitOK, nil
222	}
