272					t.Fatal(err)
273				}
274				loaded, existed, err := Load(path)
275				if err != nil || !existed {
276					t.Fatalf("%s：记录前后的合法空白不应导致拒绝，existed=%v err=%v", name, existed, err)
277				}
278				rep := loaded.CheckStudent("s1")
279				if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
280					t.Fatalf("%s：应正常读取并核对到 4 学分、要求已满足，得到 %+v", name, rep)
281				}
