303			t.Fatal(err)
304		}
305		second, err := os.ReadFile(path)
306		if err != nil {
307			t.Fatal(err)
308		}
309		if string(first) != string(second) {
310			t.Fatal("无变更重复保存应产生相同内容")
311		}
312		if _, _, err := Load(path); err != nil {
313			t.Fatalf("重复保存后文件损坏：%v", err)
314		}
315	}
316	
317	func TestSaveRejectsBadPath(t *testing.T) {
318		s := NewStore()
319		mustStudent(t, s, "s1")
320		// 目标路径的父目录不存在：应明确报错而不是静默丢失数据。
321		err := s.Save(filepath.Join(t.TempDir(), "no-such-dir", "r.json"))
322		if err == nil {
323			t.Fatal("向不存在目录保存应报错")
324		}
325	}
