			st.WaiverID = w.ID
		} else if len(entries) > 0 {
			// 没有有效免修时以最先提交的通过记录说明来源。
			st.Satisfied = true
			st.Source = "enrollment"
			st.PassedEnrollmentID = entries[0].id
		}

