// 说明只点名学生编号与溢出事实：各门课程学分本身均合法，这不是记录文件损坏。
func (rep Report) OverflowMessage() string {
	if !rep.Overflow {
		return ""
	}
	return fmt.Sprintf(
		"学生 %s 实际获得的总学分超出本程序学分整数类型可表示的最大值 %s，本次核对拒绝给出总学分",
		rep.StudentID, strconv.Itoa(math.MaxInt))
}

// zhResult 将修读结果转为中文说明。
