1	package main
2	
3	import (
4		"fmt"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件从命令行入口回归“保存时不得悄悄改写文字”。命令行参数在本机上可以
12	// 携带非法 UTF-8 字节（Go 的字符串按字节保留，不做替换），这些字节会原样
13	// 进入待保存的编号、名称、学期、依据或原因。标准库序列化会把它们静默替换成
14	// U+FFFD 却提示成功，因此保存必须明确拒绝这种数据：
15	//   - 退出码沿用保存失败的 2，标准错误说明保存失败、点名目标文件，并指出
16	//     无法原样保存的文字所在的记录类别与具体字段；
17	//   - 标准输出不能出现登记成功、免修已生效、历史已保存或文件已创建等提示；
18	//   - 已有记录文件逐字节保留、原先能查询的学生与学分照常查询；目标文件原本
19	//     不存在时不得留下新记录文件或临时文件；
20	//   - 即使问题只在一条已拒绝免修的文字里，也拒绝整次保存，历史不落盘；
21	//   - 合法文字（用户确实输入的“�”、中文与补充平面字符、编号中合法的控制
22	//     字符、依据中的空白、字面上的“\uD800”）继续正常保存使用。
23	
24	// invalidUTF8Arg 返回一个带非法 UTF-8 字节的参数。
25	func invalidUTF8Arg(prefix string) string { return prefix + string([]byte{0xFF}) }
26	
27	// assertSaveRejectsBadText 在“保存失败”通用断言之外，额外要求错误指出无法
28	// 原样保存的文字、记录类别与具体字段。
29	func assertSaveRejectsBadText(t *testing.T, file string, args []string, category, field, label string) {
30		t.Helper()
31		out, errText, code := runCLI(t, file, args...)
32		if code != exitFile {
33			t.Fatalf("%s：应按保存失败退出码 %d 结束，code=%d out=%q err=%q",
34				label, exitFile, code, out, errText)
35		}
36		if out != "" {
37			t.Fatalf("%s：保存失败时标准输出必须为空，out=%q", label, out)
38		}
39		for _, want := range []string{"保存记录文件", file, "失败", "无法原样保存", category, field} {
40			if !strings.Contains(errText, want) {
41				t.Fatalf("%s：错误输出应包含 %q（说明保存失败、目标文件、类别 %q 与字段 %q），err=%q",
42					label, want, category, field, errText)
43			}
44		}
45	}
46	
47	// TestCLISaveRejectsInvalidUTF8NotCreated 目标文件原本不存在时，待保存文字
48	// 含非法 UTF-8（学生编号、课程名称、学期、免修依据等）必须拒绝整次保存：
49	// 退出码 2、标准输出为空，目标文件与临时文件都不得留下。
50	func TestCLISaveRejectsInvalidUTF8NotCreated(t *testing.T) {
51		cases := []struct {
52			label    string
53			args     []string
54			category string
55			field    string
56		}{
57			{"学生编号非法", []string{"student", invalidUTF8Arg("s")}, "学生", "编号"},
58			{"课程编号非法", []string{"course", invalidUTF8Arg("c"), "数学", "4"}, "课程", "编号"},
59			{"课程名称非法", []string{"course", "c1", invalidUTF8Arg("数学"), "4"}, "课程", "名称"},
60			{"学期非法", []string{"enroll", "s1", "r1", invalidUTF8Arg("2024春"), "e1"}, "修读", "学期"},
61			{"免修依据非法", []string{"waiver", "s1", "r1", "w9", invalidUTF8Arg("依据")}, "免修", "依据"},
62			{"撤销原因非法", []string{"revoke-waiver", "s1", "w1", invalidUTF8Arg("原因")}, "免修", "原因"},
63		}
64		for _, c := range cases {
65			t.Run(c.label, func(t *testing.T) {
66				dir := t.TempDir()
67				file := filepath.Join(dir, "records.json")
68				// enroll/waiver/revoke 需要前置记录；这些前置命令本身必须正常落盘。
69				for _, st := range [][]string{
70					{"student", "s1"},
71					{"course", "c1", "数学", "4"},
72					{"req", "s1", "r1", "c1"},
73					{"waiver", "s1", "r1", "w1", "原始依据"},
74				} {
75					if _, errText, code := runCLI(t, file, st...); code != 0 {
76						t.Fatalf("前置步骤 %v 失败，code=%d err=%q", st, code, errText)
77					}
78				}
79				before, err := os.ReadFile(file)
80				if err != nil {
81					t.Fatal(err)
82				}
83	
84				assertSaveRejectsBadText(t, file, c.args, c.category, c.field, c.label)
85	
86				if _, statErr := os.Stat(file); statErr != nil {
87					t.Fatalf("%s：前置已创建的记录文件应继续存在：%v", c.label, statErr)
88				}
89				after, err := os.ReadFile(file)
90				if err != nil {
91					t.Fatal(err)
92				}
93				if string(before) != string(after) {
94					t.Fatalf("%s：拒绝保存后原文件必须逐字节保留\nwant=%q\n got=%q",
95						c.label, before, after)
96				}
97				leftover, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp"))
98				if len(leftover) != 0 {
99					t.Fatalf("%s：不得残留临时文件：%v", c.label, leftover)
100				}
101			})
102		}
103	}
104	
105	// TestCLISaveRejectsInvalidUTF8ForBrandNewFile 目标文件与前置数据都不存在时，
106	// 第一条登记命令的文字就非法：不得创建任何记录文件，也不能提示已登记或已
107	// 创建。
108	func TestCLISaveRejectsInvalidUTF8ForBrandNewFile(t *testing.T) {
109		file := filepath.Join(t.TempDir(), "records.json")
110		assertSaveRejectsBadText(t, file, []string{"student", invalidUTF8Arg("s")},
111			"学生", "编号", "全新文件登记非法编号学生")
112	
113		if _, err := os.Stat(file); !os.IsNotExist(err) {
114			t.Fatalf("目标文件原本不存在时不得留下新记录文件，stat err=%v", err)
115		}
116	}
117	
118	// TestCLISaveRejectedWaiverBadTextRefusesWholeSave 因目标要求不存在而本应被
119	// 拒绝、但要写入免修历史的首次申请，其依据含非法 UTF-8 时也必须拒绝整次
120	// 保存：不能只跳过历史、不能显示“已拒绝/已记入历史”，退出码 2，恢复后
121	// 历史中查不到该申请。
122	func TestCLISaveRejectedWaiverBadTextRefusesWholeSave(t *testing.T) {
123		dir := t.TempDir()
124		file := filepath.Join(dir, "records.json")
125		if _, _, code := runCLI(t, file, "student", "s1"); code != 0 {
126			t.Fatal("前置登记学生失败")
127		}
128		before, err := os.ReadFile(file)
129		if err != nil {
130			t.Fatal(err)
131		}
132	
133		out, errText, code := runCLI(t, file, "waiver", "s1", "rX", "wbad", invalidUTF8Arg("依据"))
134		if code != exitFile {
135			t.Fatalf("含非法文字的被拒绝免修应拒绝整次保存、退出码 %d，code=%d out=%q err=%q",
136				exitFile, code, out, errText)
137		}
138		if out != "" || strings.Contains(out, "已拒绝") || strings.Contains(out, "免修历史") {
139			t.Fatalf("保存失败时不得宣布申请已拒绝或历史已保存，out=%q", out)
140		}
141		if !strings.Contains(errText, "免修") || !strings.Contains(errText, "依据") {
142			t.Fatalf("错误应指出免修依据无法原样保存，err=%q", errText)
143		}
144	
145		after, err := os.ReadFile(file)
146		if err != nil {
147			t.Fatal(err)
148		}
149		if string(before) != string(after) {
150			t.Fatal("拒绝保存后原文件必须逐字节保留")
151		}
152	
153		// 重新打开进程：未保存成功的申请不在历史中，原有学生仍可查询。
154		show, _, code := runCLI(t, file, "show", "s1")
155		if code != 0 {
156			t.Fatalf("原文件应仍可正常查询，code=%d out=%q", code, show)
157		}
158		if strings.Contains(show, "wbad") {
159			t.Fatalf("未保存成功的被拒绝申请不得进入历史，out=%q", show)
160		}
161	}
162	
163	// TestCLISaveInvalidTextKeepsQueryableState 保存被拒后，原先能够查询的学生与
164	// 学分仍可正常查询；本次想写入的含非法文字内容不落盘。
165	func TestCLISaveInvalidTextKeepsQueryableState(t *testing.T) {
166		dir := t.TempDir()
167		file := filepath.Join(dir, "records.json")
168		for _, st := range [][]string{
169			{"student", "s1"},
170			{"course", "c1", "数学", "4"},
171			{"req", "s1", "r1", "c1"},
172			{"waiver", "s1", "r1", "w1", "竞赛获奖"},
173		} {
174			if _, errText, code := runCLI(t, file, st...); code != 0 {
175				t.Fatalf("前置步骤 %v 失败：%q", st, errText)
176			}
177		}
178	
179		// 试图登记名称含非法字节的第二门课程：保存失败。
180		assertSaveRejectsBadText(t, file,
181			[]string{"course", "c2", invalidUTF8Arg("物理"), "3"}, "课程", "名称", "追加非法课程")
182	
183		check, _, code := runCLI(t, file, "check", "s1")
184		if code != 0 || !strings.Contains(check, "总学分：4") ||
185			!strings.Contains(check, "来源为有效免修 w1") {
186			t.Fatalf("保存被拒后原有学分与免修来源应照常可查，code=%d out=%q", code, check)
187		}
188		list, _, code := runCLI(t, file, "list-courses")
189		if code != 0 || !strings.Contains(list, "数学") || strings.Contains(list, "物理") {
190			t.Fatalf("新课程不应落盘、旧课程应仍在，code=%d out=%q", code, list)
191		}
192	}
193	
194	// TestCLISaveAcceptsLegalUnicodeText 合法文字继续按既有规则保存与使用：
195	// 用户确实输入的“�”、中文与补充平面字符、编号中合法的控制字符、依据中的
196	// 空白、命令行字面上的“\uD800”都不能误拒绝，保存后可原样查回。
197	func TestCLISaveAcceptsLegalUnicodeText(t *testing.T) {
198		file := filepath.Join(t.TempDir(), "records.json")
199	
200		// 编号中合法的控制字符 U+0001，以及用户确实输入的“�”。
201		if out, _, code := runCLI(t, file, "student", "s\x01t"); code != 0 ||
202			!strings.Contains(out, "已登记学生") {
203			t.Fatalf("含合法控制字符的学生编号应正常登记，code=%d out=%q", code, out)
204		}
205		if _, _, code := runCLI(t, file, "student", "s�2"); code != 0 {
206			t.Fatal("用户确实输入的“�”是合法文字，应正常登记")
207		}
208		// 中文与补充平面字符课程名称。
209		if _, _, code := runCLI(t, file, "course", "c1", "高等数学😀", "4"); code != 0 {
210			t.Fatal("含补充平面字符的课程名称应正常登记")
211		}
212		if _, _, code := runCLI(t, file, "req", "s\x01t", "r1", "c1"); code != 0 {
213			t.Fatal("含控制字符编号的学生名下登记要求应正常")
214		}
215		// 学期含补充平面字符。
216		if _, _, code := runCLI(t, file, "enroll", "s\x01t", "r1", "2024😀春", "e1"); code != 0 {
217			t.Fatal("含补充平面字符的学期应正常登记")
218		}
219		// 依据含前后空白与字面上的“\uD800”（反斜线 + 普通字母数字）。
220		basis := "  竞赛获奖\t\\uD800  "
221		if out, _, code := runCLI(t, file, "waiver", "s\x01t", "r1", "w1", basis); code != 0 ||
222			!strings.Contains(out, "有效") {
223			t.Fatalf("含空白与字面 \\uD800 的依据应正常生效为有效免修，code=%d out=%q", code, out)
224		}
225	
226		// 重新打开进程，原样查回。show 用 %q 呈现依据，会把制表符与反斜线转义，
227		// 因此期望值也按同样的 %q 规则构造。
228		out, _, code := runCLI(t, file, "show", "s\x01t")
229		if code != 0 {
230			t.Fatalf("含控制字符编号应可查询，code=%d out=%q", code, out)
231		}
232		if !strings.Contains(out, "学生 s\x01t") ||
233			!strings.Contains(out, "学期 2024😀春") ||
234			!strings.Contains(out, "依据 "+fmt.Sprintf("%q", basis)) {
235			t.Fatalf("合法文字应原样保存查回，out=%q", out)
236		}
237		check, _, code := runCLI(t, file, "check", "s\x01t")
238		if code != 0 || !strings.Contains(check, "总学分：4") ||
239			!strings.Contains(check, "有效免修 w1") {
240			t.Fatalf("正常保存后学分来源与免修历史不应改变，code=%d out=%q", code, check)
241		}
242	}
