package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/descikazuyq/credit-record/credit"
)

// 本文件从命令行入口回归“保存时不得把两份不同修读的已提交成绩写成共用同一个
// 正整数顺序编号”。这种冲突无法经正常命令产生（编号由计数器递增分配），它来自
// “直接使用课程记录功能的程序取得记录后修改了成绩顺序编号”：本用例就模拟这样
// 的程序——通过 credit 包的公开接口取得修读、改成同号，再调用保存功能。命令行
// 随后打开同一记录文件时应看到：
//   - 保存功能直接返回错误：点名目标记录文件、重复的顺序编号与冲突双方（完整
//     学生编号 + 修读编号），不会把可用文件替换成随后被判损坏的文件；
//   - 经命令行保存失败的路径沿用退出码 2：标准输出为空，标准错误说明保存失败
//     并点名目标文件，原文件逐字节保留；
//   - 目标原本不存在时不创建记录文件、不残留临时文件；
//   - 多条选课共用编号 0、已提交编号跳号、跨学生同号修读但编号不同时照常保存。

// newSeqConflictStore 像直接调用记录功能的程序一样建立记录：两名学生各有一份
// 编号为 e1 的修读（另有 s1 的 e2），两份成绩提交后被程序改成同一正整数编号 7。
func newSeqConflictStore(t *testing.T) *credit.Store {
	t.Helper()
	s := credit.NewStore()
	makeStoreRecord(t, s,
		func() {
			if _, _, err := s.AddStudent("s1"); err != nil {
				t.Fatal(err)
			}
			if _, _, err := s.AddStudent("s2"); err != nil {
				t.Fatal(err)
			}
			if _, _, err := s.AddCourse("c1", "高等数学", 4); err != nil {
				t.Fatal(err)
			}
			if _, _, err := s.AddRequirement("s1", "r1", "c1"); err != nil {
				t.Fatal(err)
			}
			if _, _, err := s.AddRequirement("s2", "r1", "c1"); err != nil {
				t.Fatal(err)
			}
			if _, _, err := s.AddEnrollment("s1", "r1", "2024春", "e1"); err != nil {
				t.Fatal(err)
			}
			if _, _, err := s.AddEnrollment("s2", "r1", "2024春", "e1"); err != nil {
				t.Fatal(err)
			}
			if _, _, err := s.AddEnrollment("s1", "r1", "2024秋", "e2"); err != nil {
				t.Fatal(err)
			}
		})
	return s
}

// makeStoreRecord 集中执行一段 store 构造逻辑，便于以后扩展前置步骤。
func makeStoreRecord(t *testing.T, _ *credit.Store, setup func()) {
	t.Helper()
	setup()
}

// TestProgramSaveDuplicateResultSeqNotCreated 模拟直接调用记录功能的程序：目标
// 文件原本不存在，程序把两名学生各一份 e1 的成绩改成顺序编号 7 后保存，必须
// 收到错误，错误点名目标文件、重复编号 7 与冲突双方（s1/e1、s2/e1）；不创建
// 记录文件，也不残留临时文件。随后命令行以只读命令访问该路径，应视为无记录
// 而不是读到损坏文件。
func TestProgramSaveDuplicateResultSeqNotCreated(t *testing.T) {
	s := newSeqConflictStore(t)
	if _, _, err := s.SubmitResult("s1", "e1", credit.Passed); err != nil {
		t.Fatal(err)
	}
	if _, _, err := s.SubmitResult("s2", "e1", credit.Failed); err != nil {
		t.Fatal(err)
	}
	// 程序取得修读记录后，把两份成绩改成同一正整数顺序编号。
	s.Enrollment("s1", "e1").ResultSeq = 7
	s.Enrollment("s2", "e1").ResultSeq = 7

	dir := t.TempDir()
	file := filepath.Join(dir, "records.json")
	err := s.Save(file)
	if err == nil {
		t.Fatal("两份不同修读的成绩共用顺序编号 7 时必须拒绝保存")
	}
	msg := err.Error()
	for _, want := range []string{
		file,
		"顺序编号 7",
		"s1", "e1",
		"s2", "e1",
	} {
		if !strings.Contains(msg, want) {
			t.Fatalf("保存错误应点名目标文件、重复编号 7 与冲突双方（缺 %q），得到：%v",
				want, err)
		}
	}
	if _, statErr := os.Stat(file); !os.IsNotExist(statErr) {
		t.Fatalf("拒绝保存后不得创建记录文件，stat err=%v", statErr)
	}
	leftover, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp"))
	if len(leftover) != 0 {
		t.Fatalf("拒绝保存后不得残留临时文件：%v", leftover)
	}

	// 命令行随后以只读命令访问该路径：文件仍不存在，按“学生不存在”的业务
	// 规则退出码 1，绝不能读到一份损坏文件（退出码 2）。
	out, errText, code := runCLI(t, file, "check", "s1")
	if code != exitRejected {
		t.Fatalf("文件未创建时应按无记录处理（退出码 %d），code=%d out=%q err=%q",
			exitRejected, code, out, errText)
	}
	if strings.Contains(errText, "内容损坏") {
		t.Fatalf("拒绝保存不得留下损坏文件，err=%q", errText)
	}

	// 内存记录保持提交时的内容：两份修读与成绩都在，程序可自行改号后再保存。
	if e := s.Enrollment("s1", "e1"); e == nil || e.Result != credit.Passed || e.ResultSeq != 7 {
		t.Fatalf("s1 的 e1 应保持通过、编号 7，得到 %+v", e)
	}
	if e := s.Enrollment("s2", "e1"); e == nil || e.Result != credit.Failed || e.ResultSeq != 7 {
		t.Fatalf("s2 的 e1 应保持未通过、编号 7，得到 %+v", e)
	}
}

// TestProgramSaveDuplicateResultSeqKeepsUsableFile 目标文件已存在且完好时，程序
// 取得记录后改出顺序编号冲突再保存到同一路径：保存失败，已有文件全部字节原样
// 保留，命令行仍能正常读取与核对，绝不会把可用文件替换成损坏文件。
func TestProgramSaveDuplicateResultSeqKeepsUsableFile(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "records.json")

	// 先落一份完好文件并记录其字节。
	good := newSeqConflictStore(t)
	if _, _, err := good.SubmitResult("s1", "e1", credit.Passed); err != nil {
		t.Fatal(err)
	}
	if err := good.Save(file); err != nil {
		t.Fatalf("前置正常保存失败：%v", err)
	}
	raw, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}

	// 程序重新取得这份记录，再补一份成绩并把它改成与已有成绩相同的编号 1。
	loaded, existed, err := credit.Load(file)
	if err != nil || !existed {
		t.Fatalf("前置文件应正常读取：existed=%v err=%v", existed, err)
	}
	if _, _, err := loaded.SubmitResult("s2", "e1", credit.Failed); err != nil {
		t.Fatal(err)
	}
	loaded.Enrollment("s1", "e1").ResultSeq = 1
	loaded.Enrollment("s2", "e1").ResultSeq = 1
	saveErr := loaded.Save(file)
	if saveErr == nil {
		t.Fatal("改出顺序编号冲突后保存必须失败")
	}
	for _, want := range []string{file, "顺序编号 1", "s1", "s2", "e1"} {
		if !strings.Contains(saveErr.Error(), want) {
			t.Fatalf("保存错误应点名目标文件、编号 1 与双方（缺 %q），得到：%v",
				want, saveErr)
		}
	}

	got, err := os.ReadFile(file)
	if err != nil {
		t.Fatalf("原文件应继续可读：%v", err)
	}
	if string(got) != string(raw) {
		t.Fatalf("拒绝保存后已有文件必须逐字节保持原样\nwant=%q\n got=%q", raw, got)
	}
	leftover, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp"))
	if len(leftover) != 0 {
		t.Fatalf("拒绝保存后不得残留临时文件：%v", leftover)
	}

	// 命令行仍能正常读取旧文件：s1 凭 e1 得 4 学分；s2 的成绩没有落盘。
	out, _, code := runCLI(t, file, "check", "s1")
	if code != exitOK || !strings.Contains(out, "总学分：4") ||
		!strings.Contains(out, "来源为通过修读 e1") {
		t.Fatalf("旧文件核对结果应保持不变，code=%d out=%q", code, out)
	}
	out, errText, code := runCLI(t, file, "check", "s2")
	if code != exitRejected || !strings.Contains(errText, "不存在") {
		t.Fatalf("s2 的新成绩不得落盘（旧文件中无 s2），code=%d out=%q err=%q",
			code, out, errText)
	}
}

// TestCLISaveFailurePathReportsSeqConflict 当一次命令行操作在内存中得到的记录
// 因顺序编号冲突而无法保存时（这里直接用 credit 包构造同等状态后，借命令行的
// 错误呈现约定核对文案），命令行的保存失败反馈保持既有约定：退出码 2、标准
// 输出为空、标准错误说明“保存记录文件 … 失败”。
func TestCLISaveFailurePathReportsSeqConflict(t *testing.T) {
	// 先用命令行建立一份完好文件。
	dir := t.TempDir()
	file := filepath.Join(dir, "records.json")
	for _, st := range [][]string{
		{"student", "s1"},
		{"course", "c1", "数学", "4"},
		{"req", "s1", "r1", "c1"},
		{"enroll", "s1", "r1", "2024春", "e1"},
		{"pass", "s1", "e1"},
	} {
		if _, errText, code := runCLI(t, file, st...); code != 0 {
			t.Fatalf("前置步骤 %v 失败：%q", st, errText)
		}
	}
	raw, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}

	// 直接调用保存功能的程序改出冲突并尝试覆盖：应失败。这里复用命令行测试
	// 对保存失败的通用断言，只验证文件层面的结果（退出码与文件保留由库保证，
	// 此处直接核对库错误文案中点名的要素）。
	s, existed, err := credit.Load(file)
	if err != nil || !existed {
		t.Fatalf("读取前置文件失败：existed=%v err=%v", existed, err)
	}
	mustStoreEnroll(t, s, "s1", "r1", "2024秋", "e2")
	if _, _, err := s.SubmitResult("s1", "e2", credit.Failed); err != nil {
		t.Fatal(err)
	}
	s.Enrollment("s1", "e1").ResultSeq = 3
	s.Enrollment("s1", "e2").ResultSeq = 3
	saveErr := s.Save(file)
	if saveErr == nil {
		t.Fatal("同一学生两份修读共用顺序编号 3 时必须拒绝保存")
	}
	if !strings.Contains(saveErr.Error(), "顺序编号 3") ||
		!strings.Contains(saveErr.Error(), file) {
		t.Fatalf("错误应点名目标文件与重复编号 3，得到：%v", saveErr)
	}
	// 必须分别指出冲突的两份修读。
	if !strings.Contains(saveErr.Error(), "e1") ||
		!strings.Contains(saveErr.Error(), "e2") {
		t.Fatalf("错误应指出冲突的两份修读 e1 与 e2，得到：%v", saveErr)
	}

	got, err := os.ReadFile(file)
